\documentclass[11pt]{article}
\usepackage{amsmath, amssymb}
\usepackage{geometry}
\geometry{a4paper, margin=1in}
\title{Emergent Gauge Couplings from Filament Topology}
\author{}
\date{}

\begin{document}
\maketitle

\begin{abstract}
We derive explicit expressions for the gauge coupling constants of emergent gauge fields based on filament topological structures. Linking densities and filament scales determine the strength of the couplings without manual insertion. The resulting expressions are testable and provide clear falsifiability conditions.
\end{abstract}

\section{Emergent Gauge Coupling Constants}
In standard gauge theories, the gauge field kinetic term is:
\begin{equation}
\mathcal{L}_{\text{gauge}} = -\frac{1}{4g^2} \text{Tr}(F_{\mu\nu} F^{\mu\nu}).
\end{equation}
In the filament framework, gauge potentials $\mathcal{L}_\mu$ and field strengths $\mathcal{F}_{\mu\nu}$ emerge from local filament linking and twisting densities.

\section{Dimensional Analysis}
Gauge coupling $g$ must be dimensionless in 4D. A natural relation is:
\begin{equation}
g^{-2} \sim \rho_{\text{link}} \, \ell_f^2,
\end{equation}
where:
\begin{itemize}
    \item $\rho_{\text{link}}$ = filament linking density (number of links per unit volume),
    \item $\ell_f$ = filament transverse scale.
\end{itemize}
Thus:
\begin{equation}
g \sim \frac{1}{\sqrt{\rho_{\text{link}} \, \ell_f^2}}.
\end{equation}

\section{Specific Gauge Groups}
\begin{itemize}
    \item U(1): $g_{\text{U(1)}} \sim \frac{1}{\sqrt{\rho_{\text{winding}} \, \ell_f^2}}$.
    \item SU(2): $g_{\text{SU(2)}} \sim \frac{1}{\sqrt{\rho_{\text{link}} \, \ell_f^2}}$.
    \item SU(3): $g_{\text{SU(3)}} \sim \frac{1}{\sqrt{\rho_{\text{triple link}} \, \ell_f^2}}$.
\end{itemize}

\section{Filament Parameters}
Recall the filament transverse scale:
\begin{equation}
\ell_f = \left( \frac{2A}{T} \right)^{1/3},
\end{equation}
where $T$ is filament tension and $A$ is bending rigidity. Thus:
\begin{equation}
g \sim \frac{1}{\sqrt{\rho_{\text{link}}}} \left( \frac{T}{2A} \right)^{1/3}.
\end{equation}

\section{Predictions and Falsifiability}
The ratios of gauge couplings are predicted:
\begin{align}
\frac{g_{\text{SU(2)}}}{g_{\text{U(1)}}} &\sim \sqrt{ \frac{\rho_{\text{winding}}}{\rho_{\text{link}}} }, \\
\frac{g_{\text{SU(3)}}}{g_{\text{SU(2)}}} &\sim \sqrt{ \frac{\rho_{\text{link}}}{\rho_{\text{triple link}}} }.
\end{align}

\begin{itemize}
    \item \textbf{Falsifiability}: Discrepancy between these predictions and observed SM gauge couplings implies falsification.
\end{itemize}

\section*{References}
Placeholder for references.

\end{document}
"""

